import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;

/// The open-source icon sets the desktop's icon picker offers beside its own
/// catalogue (Procress 29 part 7): Lucide, Phosphor, Tabler — assets/icon-sets/,
/// generated by tools/icon-sets.mjs from the same packages the desktop
/// vendors. A reference is `svg:<set>/<name>`; a set is read the first time
/// one of its icons is drawn (0.5–1.5 MB of JSON each), then kept.
class IconSet {
  final String id;
  final String label;
  final String viewBox;
  final String attrs;
  final Map<String, List<dynamic>> icons; // name -> [inner SVG, search words]
  const IconSet(this.id, this.label, this.viewBox, this.attrs, this.icons);

  /// The whole SVG of one icon, `currentColor` for its colour — or null.
  String? svg(String name) {
    final i = icons[name];
    return i == null ? null : '<svg xmlns="http://www.w3.org/2000/svg" viewBox="$viewBox" $attrs>${i[0]}</svg>';
  }

  String words(String name) => (icons[name]?[1] as String?) ?? '';
}

class IconSets {
  static const ids = ['lucide', 'phosphor', 'tabler'];
  static const labels = {'lucide': 'Lucide', 'phosphor': 'Phosphor', 'tabler': 'Tabler'};
  static final _sets = <String, IconSet>{};
  static final _loading = <String, Future<IconSet?>>{};

  /// `lucide/castle` — a set's icon, not one of the app's own keys.
  static bool isSetRef(String? key) => key != null && RegExp(r'^[a-z]+/[a-z0-9-]+$').hasMatch(key);

  static IconSet? loaded(String id) => _sets[id];

  static Future<IconSet?> load(String id) {
    if (_sets[id] != null) return Future.value(_sets[id]);
    if (!ids.contains(id)) return Future.value(null);
    return _loading[id] ??= () async {
      try {
        add(id, await rootBundle.loadString('assets/icon-sets/$id.json'));
        return _sets[id];
      } catch (_) {
        return null; // a missing asset draws nothing, never throws
      }
    }();
  }

  /// For tests: a set from JSON text, as if loaded.
  static void add(String id, String json) {
    final j = jsonDecode(json) as Map<String, dynamic>;
    _sets[id] = IconSet(id, j['label'] as String, j['viewBox'] as String, j['attrs'] as String,
        (j['icons'] as Map<String, dynamic>).map((k, v) => MapEntry(k, v as List<dynamic>)));
  }
}
